def process_bid_request(req):
    if req.age_ms() > 15:
        return NO_BID  # Shed stale requests early
    user = aerospike.get_user(req.user_id, timeout_ms=3)
    ads = targeting_index.match(req.geo, req.device, user.freq_caps)[:50]
    if not ads:
        return NO_BID
    best_ad, bid = score_and_shade(req, user, ads)
    return build_bid_response(best_ad, bid) if pacer.allow(best_ad.campaign_id) else NO_BID

def get_user_profile_aerospike(client, user_id):
    try:
        _, _, record = client.get(('rtb', 'users', user_id), policy={'total_timeout': 3})
        return record
    except AerospikeTimeout:
        return ANONYMOUS_USER_DEFAULT

class LocalBudgetLease:
    def try_consume(self, amount):
        if self.remaining >= amount:
            self.remaining -= amount
            return True
        return False  # Trigger async lease renewal

def dynamic_batch_score(queue, max_wait_ms=2.0, max_items=512):
    batch = queue.drain(timeout_ms=max_wait_ms, limit=max_items)
    if not batch:
        return []
    return tensorrt_engine.execute_fp16(batch)

def apply_weight_delta(local_table, delta_packet):
    if delta_packet['version'] <= local_table.version:
        return  # Idempotent skip
    local_table.atomic_patch(delta_packet['weights'])
    local_table.version = delta_packet['version']

def watchdog_check(avg_pctr, baseline_pctr, budget_burn_rate):
    if avg_pctr > baseline_pctr * 2.0 or budget_burn_rate > 1.8:
        param_server.rollback_to_last_hourly_checkpoint()
        return 'ROLLED_BACK'
    return 'NOMINAL'
